import 'package:flutter_agent_harness/src/types.dart';
import 'package:test/test.dart';

AssistantMessage _err(String text) => AssistantMessage(
      content: const [],
      provider: 'test-provider',
      model: 'test-model',
      usage: Usage.zero,
      stopReason: StopReason.error,
      errorMessage: text,
      timestamp: DateTime.utc(2026),
    );

void main() {
  test('classifier vs new rendered timeout messages', () {
    // OLD rendering (pre-PR): toString() kept the exception class.
    final oldConnect = formatProviderError(_sendWatchedShaped());
    // ignore: avoid_print
    print('OLD-shaped connect render: $oldConnect');
    // NEW messages post-PR:
    final msgs = [
      // sendProviderFetch connect leg:
      'provider fetch (models list): no response headers within 30s (connect watchdog)',
      // sendProviderFetch read leg:
      'provider fetch (models list): response did not complete within 120s '
          '(read watchdog; FA_PROVIDER_TIMEOUT_SECONDS overrides this)',
      // codex send watchdog:
      'chatgpt-codex https://chatgpt.com/backend-api/codex/responses timed out: '
          'no response headers within 180s (connect watchdog)',
      // pre-existing _sendWatched timeout rendered BARE by the new branch:
      'Future timed out after 3:00',
      // pre-existing SSE idle watchdog rendered BARE:
      'no events from the endpoint for 300s (stream idle timeout)',
    ];
    for (final m in msgs) {
      // ignore: avoid_print
      print('transient($m) => ${isTransientTransportError(_err(m))}');
    }
    expect(
      isTransientTransportError(_err('Future timed out after 3:00')),
      isTrue,
      reason: 'the pre-existing streaming connect watchdog MUST stay transient',
    );
  });
}

// Reconstructs what formatProviderError produced BEFORE the PR for the
// streaming connect watchdog (Future.timeout without onTimeout).
TimeoutException _sendWatchedShaped() => TimeoutException(
      'Future not completed',
      effectiveProviderConnectTimeout,
    );

