Future<void> runProviderStream(
  AssistantMessageEventStream eventStream,
  ProviderStreamState state,
  CancelToken? cancelToken,
  http.Client httpClient, {
  required bool ownsClient,
  required Future<void> Function() body,
}) async {
  try {
