+    throw ConfigException(
+      'FA_PROVIDER_TIMEOUT_SECONDS must be a positive integer of seconds, '
+      'got: "$raw"',
+    );
+  }
+  return ProviderTimeoutsOverride(
+    connect: base?.connect,
+    streamIdle: base?.streamIdle,
+    fetchRead: Duration(seconds: seconds),
+  );
+}
