  final textParts = [
    for (final item in assistant.content)
      if (item is TextContent) {'type': 'output_text', 'text': item.text},
  ];
  final functionCalls = [
    for (final item in assistant.content)
      if (item is ToolCall)
        {
          'type': 'function_call',
          'call_id': item.id,
          'name': item.name,
          'arguments': jsonEncode(item.arguments),
