      // dying pipeline and may itself fail (issue #921).
      onAbandon?.call();
      unawaited(_quietCancel(_inner.cancel()));
      completer.completeError(
        TimeoutException(
          'no events from the endpoint for '
          '${_idleTimeout.inSeconds}s (stream idle timeout)',
          _idleTimeout,
        ),
      );
