+ProviderTimeoutsOverride? applyProviderTimeoutEnvOverride(
+  ProviderTimeoutsOverride? base,
+  String? raw,
+) {
+  if (raw == null || raw.trim().isEmpty) return base;
+  final seconds = int.tryParse(raw.trim());
