Future<ChatGptOAuthCredentials> _tokenRequest(
  Map<String, String> fields, {
  http.Client? client,
  bool jsonBody = false,
}) async {
  final httpClient = client ?? http.Client();
  final ownsClient = client == null;
  try {
    // Issue #1036: ride the shared fetch watchdogs (connect 30s / read
    // 120s, FA_PROVIDER_TIMEOUT_SECONDS overrides the read leg) instead of
    // a hard-coded 30s — token refresh is on the agent's critical path.
    final request = http.Request('POST', Uri.parse('$chatGptIssuer/oauth/token'))
      ..headers['Content-Type'] = jsonBody
          ? 'application/json'
          : 'application/x-www-form-urlencoded'
      ..body = jsonBody
          ? jsonEncode(fields)
          : fields.entries
                .map(
                  (e) =>
                      '${Uri.encodeQueryComponent(e.key)}=${Uri.encodeQueryComponent(e.value)}',
                )
                .join('&');
    final response = await sendProviderFetch(
      httpClient,
      request,
      endpoint: 'ChatGPT OAuth token',
    );
    final body = _jsonObject(response.body);
    if (response.statusCode < 200 || response.statusCode >= 300) {
      throw ConfigException(
        'ChatGPT OAuth token request failed (${response.statusCode}): ${body['error_description'] ?? body['error'] ?? response.body}',
      );
    }
    String token(String name, {bool required = true}) {
      final value = body[name];
      if (value is String && value.isNotEmpty) return value;
      if (!required) return '';
      throw ConfigException('ChatGPT OAuth token response has no $name');
    }

    final idToken = token('id_token', required: false);
    final expiresIn = body['expires_in'];
    return ChatGptOAuthCredentials(
      accessToken: [REDACTED:Sensitive Value]'access_token'),
      refreshToken: [REDACTED:Sensitive Value]'refresh_token', required: false),
      idToken: idToken,
      accountId: _accountIdFromJwt(idToken),
      expiresAt: expiresIn is int
          ? DateTime.now().toUtc().add(Duration(seconds: expiresIn))
          : null,
    );
  } on ConfigException {
    rethrow;
  } on Object catch (error) {
    throw ConfigException('ChatGPT OAuth token request failed: $error');
  } finally {
    if (ownsClient) httpClient.close();
  }
}

Map<String, dynamic> _jsonObject(String body) {
  try {
