AssistantMessageEventStream streamChatGptCodex(
  Model model,
  Context context, {
  required String credentials,
  ChatGptCredentialsPersist? onCredentialsRefreshed,
  CancelToken? cancelToken,
  http.Client? client,
}) {
  final events = AssistantMessageEventStream();
