  StreamSubscription<List<int>>? rawSub;
  final body = StreamController<List<int>>(
    onPause: () => rawSub?.pause(),
    onResume: () => rawSub?.resume(),
    onCancel: () {
      abandon();
      return rawSub?.cancel() ?? Future<void>.value();
    },
  );
